function CountOddDigits(s: string): int
    requires s.Length > 0
    ensures 0 <= CountOddDigits(s) <= s.Length
{
    var count := 0;
    var i := 0;
    while i < s.Length
        invariant 0 <= count <= i
        invariant i <= s.Length
    {
        if (s[i] - '0') % 2 == 1 {
            count := count + 1;
        }
        i := i + 1;
    }
    return count;
}
